const raw = $input.first().json || {};
let j = raw;
if (typeof raw.content === 'string') {
  try { j = JSON.parse(raw.content); } catch (e) { j = raw; }
} else if (raw.content && typeof raw.content === 'object') {
  j = raw.content;
}
const type = String(j.type || j.event_type || j.routing_key || raw.type || '').trim();
const userId = j.userId || j.user_id || j.properties?.userId || '';
const phone = j.phone || j.properties?.phone || '';
const email = j.email || j.properties?.email || '';
const name = j.name || j.properties?.name || '';
const movieId = j.movie_id || j.properties?.movieId || '';
const movieTitle = j.movie_title || j.properties?.movieTitle || '';
const isWelcome = type === 'user.signed_up' || type === 'signup' || type === 'user_signed_up';
const isWatch = type === 'watch_complete';
return [{
  json: {
    ...j,
    type,
    userId,
    user_id: userId,
    phone,
    email,
    name,
    movie_id: movieId,
    movie_title: movieTitle,
    session_id: j.session_id || j.properties?.sessionId || null,
    channel_pref: j.channel_pref || j.channelPref || j.properties?.channelPref || 'both',
    isWelcome,
    isWatch,
    route: isWelcome ? 'welcome' : isWatch ? 'watch' : 'skip',
  },
}];

const event = $('Normalize event').first().json;
const items = ($('Welcome · Pick film').first().json?.data?.items || []).slice(0, 3);
const pick = items[0];
const person = $('Welcome · Contacts').first().json || {};
const first = String(person.name || event.name || 'there').trim().split(/\s+/)[0] || 'there';
const store = String($env.STOREFRONT_URL || 'http://localhost:18080').replace(/\/$/, '');
const url = pick?.pageUrl || (store + '/browse');
const poster = pick?.poster || pick?.posterUrl || '';
const titles = items.map((i) => i.title).filter(Boolean);
let message = pick
  ? ('Karibu ' + first + '! Start with ' + titles.join(' · ') + ' — from KES ' + pick.priceKes + '. Trailer: ' + url)
  : ('Karibu ' + first + '! Browse Kenyan & African films from KES 5 on Yakwetu Sinema: ' + store + '/browse');
if (message.length > 280) message = message.slice(0, 277) + '...';
const phone = person.phone || event.phone || '';
const email = person.email || event.email || '';
return [{ json: {
  userId: event.userId,
  phone,
  email,
  name: person.name || event.name || first,
  channelPref: person.channel_pref || person.channelPref || event.channel_pref || 'both',
  subject: pick ? ('Karibu ' + first + ' — start with ' + pick.title) : ('Karibu ' + first + ' — Yakwetu Sinema'),
  scenario: 'journey_welcome',
  firstName: first,
  filmTitle: pick?.title || null,
  pickTitle: pick?.title || null,
  bundleTitle: titles.length > 1 ? titles.slice(1).join(' + ') : null,
  genre: (pick?.genres && pick.genres[0]) || '',
  priceKes: pick?.priceKes || 5,
  url,
  ctaUrl: url,
  ctaLabel: 'Watch the trailer',
  imageUrl: poster,
  message,
  fallback: message,
  recommendedFilms: items.map((i) => ({
    title: i.title,
    genre: (i.genres && i.genres[0]) || '',
    priceKes: i.priceKes,
    id: i.movieId || i.id,
  })),
}}];

