let message = '';
let error = null;
try {
  const raw = $input.first().json || {};
  if (raw.error || raw.message === 'Unauthorized' || raw.code === 401) error = String(raw.error || raw.message || 'openrouter_error');
  const content = (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content) || '';
  if (typeof content === 'string' && content.trim().startsWith('{')) {
    const parsed = JSON.parse(content);
    message = String(parsed.message || parsed.text || '').trim();
  } else if (typeof content === 'string' && !error) message = content.trim();
} catch (e) { error = String(e.message || e); }
return [{ json: { output: { message }, text: message, error } }];

const facts = $("Welcome · Write message").first().json || {};
const ai = $input.first().json || {};
const text = String((ai.output && ai.output.message) || ai.text || '').trim();
let fallbackReason = null;
if (!text) fallbackReason = ai.error ? ('AI error: ' + ai.error) : 'no AI answer';
else if (text.length > 140) fallbackReason = 'too long';
else if (/https?:|www\./i.test(text)) fallbackReason = 'contains a link';
const body = fallbackReason ? (facts.fallback || facts.message || '') : text;
const url = facts.url || facts.ctaUrl || '';
const message = url ? `${body} ${url}`.trim() : body;
return [{ json: { ...facts, message, aiUsed: !fallbackReason, fallbackReason } }];

